# Installs the Python package k13m, generated by JGraph's mcc:
#     python -m pip install .
# from the folder this file is in.

try:
    from setuptools import setup
except ImportError:
    raise EnvironmentError("Installation failed. Install setuptools using 'python -m pip install setuptools', then try again.")

if __name__ == '__main__':
    setup(
        name='k13m-R2025b',
        version='25.2',
        description='A Python interface to k13m',
        platforms=['Windows'],
        packages=[
            'k13m'
        ],
        package_data={'k13m': ['*.ctf']},
    )
